const directory = `src/test/resources/dt-fixtures/${vars.name}`;
let base = await tools.testdb_template_build({ workspace: vars.workspace, directory }).catch(e => { throw new Error(/not initialized|no test database/.test(e.message) ? `${e.message} (one time per scratch cluster: tests.pgUrl in config.json, then testdb_initialize)` : e.message); });
for (let i = 0; i < 300 && ['running', 'queued', 'building'].includes(base.state); i++) { await new Promise(r => setTimeout(r, 1000)); base = await tools.testdb_template_build({ job: base.job }); }
if (base.error || !['ready', 'done'].includes(base.state)) throw new Error(`template ${base.state || ''}: ${base.error || 'not ready'}`);
const template = base.id || base.template || base.key;
let run = null;
if (vars.tests) {
  run = await tools.test_run({ workspace: vars.workspace, tests: vars.tests.split(',').map(s => s.trim()), fixture_template: template });
  for (let i = 0; i < 600 && run.state === 'running'; i++) { await new Promise(r => setTimeout(r, 1000)); run = await tools.test_run({ workspace: vars.workspace, job: run.job }); }
  test('tests pass on the fixture', () => expect(run.failed ?? (run.ok === false ? 1 : 0)).toBe(0));
}
return { template, directory, databases: Object.fromEntries(Object.entries(base.databases || {}).map(([db, x]) => [db, (x.tables || []).map(t => `${t.schema}.${t.name}: ${t.rows}`)])), reused: !!base.reused, run: run && { passed: run.passed, failed: run.failed, view: run.view }, next: run ? undefined : `test_run with fixture_template=${template}` };
